private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int len = descriptor.length();
    if (len == 0) {
        throw new IllegalArgumentException("Descriptor cannot be empty");
    }
    int index = 0;
    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types
        index = 1;
        while (index < len && descriptor.charAt(index) != ')') {
            int slots = 1;
            char c = descriptor.charAt(index);
            if (c == 'J' || c == 'D') {
                slots = 2;
                index++;
            } else if (c == '[') {
                // Array type: consume '['s
                while (index < len && descriptor.charAt(index) == '[') {
                    index++;
                }
                if (index >= len) {
                    throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
                }
                // Skip element type
                char elem = descriptor.charAt(index);
                if (elem == 'L') {
                    index++;
                    while (index < len && descriptor.charAt(index) != ';') {
