    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        return (char) intVal;
    }

    if (value instanceof Boolean) {
        // Optional: map true/false to 't'/'f'
        return ((Boolean) value) ? 't' : 'f';
    }

    throw new Exception("Unsupported conversion to Character: " + value.getClass().getName());
}

