private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        // Nothing to move if the source bucket is already the target bucket
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new java.util.HashSet<>();
        bucketsByLabel.set(0, target);
    }
    try {
        for (Integer v : source) {
            if (v == null) {
                continue;
            }
            if (v < 0 || v >= labels.size()) {
                throw new IllegalArgumentException("Vertex index " + v + " out of bounds for labels list");
            }
            target.add(v);
            labels.set(v, 0);
        }
    } catch (RuntimeException e) {
        throw new IllegalArgumentException("Failed to reload buckets", e);
    }
    source.clear();
}

