private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        if (!graph.containsVertex(vi)) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (!graph.containsVertex(vj)) {
                return false;
            }
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

