public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');
    // No dot after the last slash, or dot is the last character, or dot is the first character of the filename
    if (lastDot <= lastSlash || lastDot == path.length() - 1 || lastDot == lastSlash + 1) {
        return null;
    }
    return path.substring(0, lastDot);
}

