public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds");
    }
    if (pane.getViewport().getView() != table) {
        throw new IllegalArgumentException("Table does not belong to the specified JScrollPane");
    }
    SwingUtilities.invokeLater(() -> {
        table.setRowSelectionInterval(row, row);
        java.awt.Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }
        SwingUtilities.invokeLater(() -> table.repaint());
    });
}

