            }
            configDir = new File(userHome, "lf5");
        }

        if (configDir.exists()) {
            if (!configDir.isDirectory()) {
                throw new IllegalStateException("Configuration path exists but is not a directory: " + configDir.getAbsolutePath());
            }
            // Directory already exists; nothing more to do
            return;
        }

        if (!configDir.mkdirs()) {
            throw new IllegalStateException("Failed to create configuration directory: " + configDir.getAbsolutePath());
        }
    } catch (SecurityException se) {
        throw new IllegalStateException("Insufficient permissions to create configuration directory", se);
    }
}

