public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new java.io.FileNotFoundException("File not found: " + file);
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (timeRanges == null || timeRanges.isEmpty()) {
        return result; // no ranges to filter, return empty list
    }
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static parse method
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a snapshot
                continue;
            }
            long timestamp;
            try {
                // Assume ThreadSnapshot has a getTimestamp method
                timestamp = snapshot.getTimestamp();
            } catch (Exception e) {
                // If timestamp cannot be retrieved, skip this snapshot
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime();
                long end = range.getEndTime();
                if (timestamp >= start && timestamp <= end) {
                    inRange = true;
                    break;
                }
            }
            if (inRange) {
                result.add(snapshot);
            }
        }
    }
    return result;
}

