            // Method descriptor: pop argument types only
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            int i = 1; // skip '('
            while (i < end) {
                char c = descriptor.charAt(i);
                // Skip array brackets
                while (c == '[') {
                    i++;
                    if (i >= end) {
                        throw new IllegalArgumentException("Invalid array type in descriptor");
                    }
                    c = descriptor.charAt(i);
                }
                if (c == 'L') {
                    // Object type: skip until ';'
                    int semicolon = descriptor.indexOf(';', i);
                    if (semicolon == -1 || semicolon > end) {
                        throw new IllegalArgumentException("Invalid object type in descriptor");
                    }
                    i = semicolon + 1;
                } else {
                    // Primitive type: single character
                    i++;
                }
                count++;
            }
        } else {
            // Type descriptor: pop the type itself
            int i = 0;
            while (i < descriptor.length()) {
                char c = descriptor.charAt(i);
                // Skip array brackets
                while (c == '[') {
                    i++;
                    if (i >= descriptor.length()) {
                        throw new IllegalArgumentException("Invalid array type in descriptor");
                    }
                    c = descriptor.charAt(i);
