public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String is null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non-negative");
    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Index + length exceeds string length");
    }

    int size = 0;
    int i = 0;
    while (i < len) {
        int pos = index + i;
        char ch = str.charAt(pos);

        // Check for surrogate pair
        if (Character.isHighSurrogate(ch) && i + 1 < len) {
            int nextPos = index + i + 1;
            char low = str.charAt(nextPos);
            if (Character.isLowSurrogate(low)) {
                int codePoint = Character.toCodePoint(ch, low);
                if (codePoint <= 0x7FF) {
                    size += 2;
                } else if (codePoint <= 0xFFFF) {
                    size += 3;
                } else {
                    size += 4;
                }
                i += 2; // Skip both surrogate characters
                continue;
            }
        }

        // Single character
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            size += 3;
        }
        i++;
    }
    return size;
}

